<template>
  <section class="narriva-modes" :class="{'narriva-modes--compact':compact}" aria-label="Note writing method">
    <div v-if="!compact" class="narriva-modes__heading"><div><span>Note Workspace</span><h2>How would you like to document this session?</h2></div><img :src="NARRIVA_BRAND.logo" alt="Narriva by AuricWell" /></div>
    <div class="narriva-modes__options" role="group" aria-label="Note writer">
      <button v-for="mode in NARRIVA_MODES" :key="mode.id" type="button" :disabled="disabled || !isAllowed(mode.id)" :aria-pressed="modelValue === mode.id" :class="{ selected: modelValue === mode.id }" @click="$emit('update:modelValue', mode.id)">
        <img v-if="mode.id === 'narriva'" :src="NARRIVA_BRAND.icon" alt="" />
        <span v-else class="narriva-modes__symbol" aria-hidden="true">{{ mode.id === 'manual' ? '✎' : '☷' }}</span>
        <span><strong>{{ mode.label }}</strong><small>{{ mode.detail }}</small><em v-if="defaultMode === mode.id">Your default</em></span>
      </button>
    </div>
    <div class="narriva-modes__footer"><span v-if="!allowManual">Manual writing is unavailable under your profile settings.</span><span v-else-if="!allowSmart">Smart Notes is unavailable for this note type.</span><span v-else>Your content stays with this note when you switch methods.</span><button type="button" :disabled="saving || disabled || modelValue === defaultMode || !isAllowed(modelValue)" @click="$emit('save-default', modelValue)">{{ saving ? 'Saving…' : 'Set as my default' }}</button></div>
    <p v-if="error" role="alert" class="narriva-modes__error">{{ error }}</p>
  </section>
</template>
<script setup>
import { NARRIVA_BRAND, NARRIVA_MODES } from '../../config/narrivaBrand.js';
const props = defineProps({ modelValue: { type: String, default: 'manual' }, defaultMode: { type: String, default: 'manual' }, allowManual: { type: Boolean, default: true }, allowNarriva: { type:Boolean, default:true }, allowSmart: { type: Boolean, default: true }, compact:Boolean, disabled: Boolean, saving: Boolean, error: { type: String, default: '' } });
defineEmits(['update:modelValue', 'save-default']);
const isAllowed = mode => (mode !== 'manual' || props.allowManual) && (mode !== 'narriva' || props.allowNarriva) && (mode !== 'smart_notes' || props.allowSmart);
</script>
